ON DUPLICATE KEY UPDATE
    var_name = VALUES(var_name),
    var_type = VALUES(var_type),
    var_address = VALUES(var_address),
    is_storage = VALUES(is_storage),
    update_user = VALUES(update_user),
    update_time = VALUES(update_time);

-- 验证配置
SELECT d.device_code, COUNT(v.id) as point_count
FROM device d
LEFT JOIN device_variable v ON d.id = v.device_id
WHERE d.device_code LIKE 'agv%'
GROUP BY d.device_code;

-- 验证 item_id 映射
SELECT id, device_id, var_seq, var_name, var_address
FROM device_variable
WHERE device_id >= {DEVICE_ID_START} AND device_id < {DEVICE_ID_START + len(AGV_DEVICES)}
LIMIT 10;